def enable_vt_colors():
    if os.name == 'nt':
        try:
            kernel32 = ctypes.windll.kernel32
            handle = kernel32.GetStdHandle(-11)
            mode = ctypes.c_uint32()
            if kernel32.GetConsoleMode(handle, ctypes.byref(mode)):
                kernel32.SetConsoleMode(handle, mode.value | 0x0004)
            kernel32.SetConsoleTitleW('FreeEDR Comment Cleaner')
        except Exception:
            pass


class LexError(Exception):
    pass


class CSharpLexer:
    """Classifies every character of a C# source file into a token kind.

    Handles // and /* */ comments, /// and /** */ doc comments, preprocessor lines, char literals,
    regular, verbatim (@""), interpolated ($"", $@"", @$"") and raw ($$\"\"\"...\"\"\") strings, including
    interpolation holes that contain nested strings. Raises LexError on anything unterminated so that
    the caller can refuse to edit a file it does not fully understand.
    """

    STRING_START_RE = re.compile(r'(\$+@?|@\$+|@)?("{3,}|")')
    PP_MESSAGE_RE = re.compile(r'#\s*(?:region|endregion|error|warning)\b')

    def __init__(self, text):
        self.s = text
        self.n = len(text)
        self.kinds = bytearray(self.n)

    def mark(self, kind, a, b):
        if b > a:
            self.kinds[a:b] = bytes([kind]) * (b - a)

    def run(self):
        end = self.code(0, hole=False)
        if end != self.n:
            raise LexError(f'unbalanced closing brace in interpolation at offset {end}')
        return self.kinds

    def at_line_start(self, i):
        j = i - 1
        while j >= 0 and self.s[j] in ' \t':
            j -= 1
        return j < 0 or self.s[j] == '\n'

    def code(self, i, hole):
        s, n = self.s, self.n
        depth = 0
        while i < n:
            c = s[i]
            if c == '/' and i + 1 < n and s[i + 1] == '/':
                j = s.find('\n', i)
                j = n if j < 0 else j
                if j > i and s[j - 1] == '\r':
                    j -= 1
                is_doc = s.startswith('///', i) and not s.startswith('////', i)
                self.mark(DOC if is_doc else LCOM, i, j)
                i = j
                continue
            if c == '/' and i + 1 < n and s[i + 1] == '*':
                j = s.find('*/', i + 2)
                if j < 0:
                    raise LexError(f'unterminated block comment at offset {i}')
                is_doc = s.startswith('/**', i) and not s.startswith('/**/', i)
                self.mark(DOC if is_doc else BCOM, i, j + 2)
                i = j + 2
                continue
            if c == '#' and not hole and self.at_line_start(i):
                j = s.find('\n', i)
                j = n if j < 0 else j
                if j > i and s[j - 1] == '\r':
                    j -= 1
                self.mark(PRE, i, j)
                if not self.PP_MESSAGE_RE.match(s, i):
                    k, quoted = i, False
                    while k < j - 1:
                        if s[k] == '"':
                            quoted = not quoted
                        elif not quoted and s.startswith('//', k):
                            self.mark(LCOM, k, j)
                            break
                        k += 1
                i = j
                continue
            if c == "'":
                i = self.char_literal(i)
                continue
            if c in '"$@':
                m = self.STRING_START_RE.match(s, i)
                if m and not (i > 0 and (s[i - 1].isalnum() or s[i - 1] == '_') and c != '"'):
                    i = self.string_literal(i, m)
                    continue
            if hole:
                if c == '{':
                    depth += 1
                elif c == '}':
                    if depth == 0:
                        return i + 1
                    depth -= 1
            i += 1
        if hole:
            raise LexError('unterminated interpolation hole')
        return i

    def char_literal(self, i):
        s, n = self.s, self.n
        j = i + 1
        while j < n and s[j] != "'":
            if s[j] == '\\':
                j += 1
            if j < n and s[j] == '\n':
                raise LexError(f'unterminated char literal at offset {i}')
            j += 1
        if j >= n:
            raise LexError(f'unterminated char literal at offset {i}')
        self.mark(CHR, i, j + 1)
        return j + 1

    def string_literal(self, i, m):
        prefix, quotes = m.group(1) or '', m.group(2)
        dollars = prefix.count('$')
        verbatim = '@' in prefix
        start = i
        i = m.end()
        if len(quotes) >= 3 and not verbatim:
            return self.raw_string(start, i, len(quotes), dollars)
        if len(quotes) >= 3 and verbatim:
            i = m.start(2) + 1
        elif len(quotes) == 2:
            i = m.start(2) + 1
        return self.quoted_string(start, i, verbatim, dollars > 0)

    def quoted_string(self, start, i, verbatim, interpolated):
        s, n = self.s, self.n
        seg = start
        while i < n:
            c = s[i]
            if c == '\\' and not verbatim:
                i += 2
                continue
            if c == '"':
                if verbatim and i + 1 < n and s[i + 1] == '"':
                    i += 2
                    continue
                self.mark(STR, seg, i + 1)
                return i + 1
            if c == '\n' and not verbatim:
                raise LexError(f'newline in regular string literal at offset {start}')
            if interpolated and c == '{':
                if i + 1 < n and s[i + 1] == '{':
                    i += 2
                    continue
                self.mark(STR, seg, i + 1)
                i = self.code(i + 1, hole=True)
                seg = i - 1
                continue
            if interpolated and c == '}' and i + 1 < n and s[i + 1] == '}':
                i += 2
                continue
            i += 1
        raise LexError(f'unterminated string literal at offset {start}')

    def raw_string(self, start, i, quote_count, dollars):
        s, n = self.s, self.n
        closing = '"' * quote_count
        seg = start
        while i < n:
            if s.startswith(closing, i):
                j = i
                while j < n and s[j] == '"':
                    j += 1
                self.mark(STR, seg, j)
                return j
            if dollars and s[i] == '{':
                j = i
                while j < n and s[j] == '{':
                    j += 1
                run = j - i
                if run >= dollars:
                    self.mark(STR, seg, j)
                    k = self.code(j, hole=True)
                    for _ in range(dollars - 1):
                        if k < n and s[k] == '}':
                            k += 1
                        else:
                            raise LexError(f'raw interpolation hole not closed with {dollars} braces at {k}')
                    seg = k - dollars
                    i = k
                    continue
                i = j
                continue
            i += 1
        raise LexError(f'unterminated raw string literal at offset {start}')


class JsLexer:
    """Classifies JavaScript: // and /* */ comments (/** */ = doc), '...' and "..." strings, `...`
    templates with nested ${...} holes, and regex literals."""

    REGEX_AFTER_WORDS = {'return', 'typeof', 'instanceof', 'in', 'of', 'new', 'delete', 'void', 'throw',
                         'case', 'do', 'else', 'yield', 'await'}
    REGEX_AFTER_CHARS = set('(,=:[!&|?{};+-*%<>~^')

    def __init__(self, text):
        self.s = text
        self.n = len(text)
        self.kinds = bytearray(self.n)

    def mark(self, kind, a, b):
        if b > a:
            self.kinds[a:b] = bytes([kind]) * (b - a)

    def run(self):
        end = self.code(0, hole=False)
        if end != self.n:
            raise LexError(f'unbalanced closing brace in template hole at offset {end}')
        return self.kinds

    def code(self, i, hole):
        s, n = self.s, self.n
        depth, prev, prev_word = 0, None, ''
        while i < n:
            c = s[i]
            if c.isspace():
                i += 1
                continue
            if c == '/' and i + 1 < n and s[i + 1] == '/':
                j = s.find('\n', i)
                j = n if j < 0 else j
                if j > i and s[j - 1] == '\r':
                    j -= 1
                self.mark(LCOM, i, j)
                i = j
                continue
            if c == '/' and i + 1 < n and s[i + 1] == '*':
                j = s.find('*/', i + 2)
                if j < 0:
                    raise LexError(f'unterminated block comment at offset {i}')
                is_doc = s.startswith('/**', i) and not s.startswith('/**/', i)
                self.mark(DOC if is_doc else BCOM, i, j + 2)
                i = j + 2
                continue
            if c in '"\'':
                i = self.string(i, c)
                prev, prev_word = 'a', ''
                continue
            if c == '`':
                i = self.template(i)
                prev, prev_word = 'a', ''
                continue
            if c == '/':
                if prev is None or prev in self.REGEX_AFTER_CHARS or (prev == 'a' and prev_word in self.REGEX_AFTER_WORDS):
                    i = self.regex(i)
                    prev, prev_word = 'a', ''
                    continue
                prev, prev_word = '/', ''
                i += 1
                continue
            if c.isalnum() or c in '_$#':
                j = i + 1
                while j < n and (s[j].isalnum() or s[j] in '_$'):
                    j += 1
                prev, prev_word = 'a', s[i:j]
                i = j
                continue
            if hole:
                if c == '{':
                    depth += 1
                elif c == '}':
                    if depth == 0:
                        return i + 1
                    depth -= 1
            prev, prev_word = c, ''
            i += 1
        if hole:
            raise LexError('unterminated template hole')
        return i

    def string(self, i, quote):
        s, n = self.s, self.n
        j = i + 1
        while j < n:
            c = s[j]
            if c == '\\':
                j += 3 if s.startswith('\r\n', j + 1) else 2
                continue
            if c == quote:
                self.mark(STR, i, j + 1)
                return j + 1
            if c == '\n':
                raise LexError(f'newline in string literal at offset {i}')
            j += 1
        raise LexError(f'unterminated string literal at offset {i}')

    def template(self, i):
        s, n = self.s, self.n
        seg, j = i, i + 1
        while j < n:
            c = s[j]
            if c == '\\':
                j += 2
                continue
            if c == '`':
                self.mark(STR, seg, j + 1)
                return j + 1
            if c == '$' and j + 1 < n and s[j + 1] == '{':
                self.mark(STR, seg, j + 2)
                k = self.code(j + 2, hole=True)
                seg, j = k - 1, k
                continue
            j += 1
        raise LexError(f'unterminated template literal at offset {i}')

    def regex(self, i):
        s, n = self.s, self.n
        j, in_class = i + 1, False
        while j < n:
            c = s[j]
            if c == '\\':
                j += 2
                continue
            if c in '\r\n':
                raise LexError(f'unterminated regex literal at offset {i}')
            if c == '[':
                in_class = True
            elif c == ']':
                in_class = False
            elif c == '/' and not in_class:
                j += 1
                while j < n and s[j].isalpha():
                    j += 1
                self.mark(STR, i, j)
                return j
            j += 1
        raise LexError(f'unterminated regex literal at offset {i}')


def lex_xaml(text):
    """<!-- --> = block comment, <![CDATA[ ]]> and quoted attribute values = string, <? ?> = preprocessor."""
    n = len(text)
    kinds = bytearray(n)

    def mark(kind, a, b):
        kinds[a:b] = bytes([kind]) * (b - a)

    i, in_tag = 0, False
    while i < n:
        for opener, closer, kind in (('<!--', '-->', BCOM), ('<![CDATA[', ']]>', STR), ('<?', '?>', PRE)):
            if not in_tag and text.startswith(opener, i):
                j = text.find(closer, i + len(opener))
                if j < 0:
                    raise LexError(f'unterminated {opener} at offset {i}')
                mark(kind, i, j + len(closer))
                i = j + len(closer)
                break
        else:
            c = text[i]
            if not in_tag and c == '<':
                in_tag = True
            elif in_tag and c in '"\'':
                j = text.find(c, i + 1)
                if j < 0:
                    raise LexError(f'unterminated attribute value at offset {i}')
                mark(STR, i, j + 1)
                i = j + 1
                continue
            elif in_tag and c == '>':
                in_tag = False
            i += 1
    return kinds


class YaraLexer(JsLexer):
    REGEX_AFTER_WORDS = {'matches'}
    REGEX_AFTER_CHARS = set('=(')


CMD_COMMENT_RE = re.compile(r'[ \t]*(@?[Rr][Ee][Mm](?=$|[ \t.:/\\(,;=+\[\]])|::)')


def ends_with_caret(line):
    """True when the line ends with an odd number of ^ (cmd joins the next line to it; ^^ is a literal ^)."""
    body = line.rstrip(' \t')
    return (len(body) - len(body.rstrip('^'))) % 2 == 1


def lex_cmd(text):
    kinds = bytearray(len(text))
    continued = False
    for a, b, _ in split_lines(text):
        line = text[a:b]
        if not continued:
            m = CMD_COMMENT_RE.match(line)
            if m:
                kinds[a + m.start(1):b] = bytes([LCOM]) * (b - a - m.start(1))
        continued = ends_with_caret(line)
    return kinds


INNO_SECTION_RE = re.compile(r'[ \t]*\[([A-Za-z]+)\][ \t]*$')


def lex_iss(text):
    """Sections: a line starting with ; = comment, # = ISPP directive. [Code] (Pascal Script):
    // line, { } and (* *) block comments, '...' strings ('' = quote), {#...} = ISPP inline (kept)."""
    s, n = text, len(text)
    kinds = bytearray(n)

    def mark(kind, a, b):
        if b > a:
            kinds[a:b] = bytes([kind]) * (b - a)

    def line_end(i):
        j = s.find('\n', i)
        j = n if j < 0 else j
        return j - 1 if j > i and s[j - 1] == '\r' else j

    in_code, i = False, 0
    while i < n:
        if i == 0 or s[i - 1] == '\n':
            j = line_end(i)
            line = s[i:j]
            m = INNO_SECTION_RE.match(line)
            if m:
                in_code = m.group(1).lower() == 'code'
                i = j
                continue
            stripped = line.lstrip(' \t')
            off = i + len(line) - len(stripped)
            if stripped.startswith('#'):
                mark(PRE, off, j)
                i = j
                continue
            if not in_code:
                if stripped.startswith(';'):
                    mark(LCOM, off, j)
                i = j if j > i else i + 1
                continue
        if not in_code:
            i += 1
            continue
        if s.startswith('//', i):
            j = line_end(i)
            mark(LCOM, i, j)
            i = j
            continue
        if s[i] == '{':
            j = s.find('}', i + 1)
            if j < 0:
                raise LexError(f'unterminated {{ at offset {i}')
            mark(STR if s.startswith('{#', i) else BCOM, i, j + 1)
            i = j + 1
            continue
        if s.startswith('(*', i):
            j = s.find('*)', i + 2)
            if j < 0:
                raise LexError(f'unterminated (* at offset {i}')
            mark(BCOM, i, j + 2)
            i = j + 2
            continue
        if s[i] == "'":
            j = i + 1
            while True:
                if j >= n or s[j] in '\r\n':
                    raise LexError(f'unterminated string literal at offset {i}')
                if s[j] == "'":
                    if j + 1 < n and s[j + 1] == "'":
                        j += 2
                        continue
                    break
                j += 1
            mark(STR, i, j + 1)
            i = j + 1
            continue
        i += 1
    return kinds


def python_ast(text):
    with warnings.catch_warnings():
        warnings.simplefilter('ignore')
        return ast.dump(ast.parse(text))


def analyze_python(text):
    starts = [0] + [m.end() for m in re.finditer('\n', text)]
    kinds = bytearray(len(text))
    try:
        with warnings.catch_warnings():
            warnings.simplefilter('ignore')
            tokens = list(tokenize.generate_tokens(io.StringIO(text).readline))
    except (tokenize.TokenError, SyntaxError) as exc:
        raise LexError(f'Python tokenizer failed ({exc})')

    def offset(pos):
        return starts[pos[0] - 1] + pos[1]

    open_strings = []
    for tok in tokens:
        name = tokenize.tok_name.get(tok.type, '')
        if name.endswith('STRING_START'):
            open_strings.append(offset(tok.start))
            continue
        if name.endswith('STRING_END') and open_strings:
            a = open_strings.pop()
            if not open_strings:
                kinds[a:offset(tok.end)] = bytes([STR]) * (offset(tok.end) - a)
            continue
        if open_strings:
            continue
        a, b = offset(tok.start), offset(tok.end)
        if tok.type == tokenize.COMMENT:
            if text[a:b] != tok.string:
                raise LexError(f'tokenizer offsets do not match the file at line {tok.start[0]}')
            kinds[a:b] = bytes([LCOM]) * (b - a)
        elif tok.type == tokenize.STRING:
            kinds[a:b] = bytes([STR]) * (b - a)
    try:
        python_ast(text)
        problem = None
    except SyntaxError as exc:
        problem = f'Python syntax error at line {exc.lineno}: {exc.msg}'
    return kinds, problem


def python_equivalent(old_text, new_text):
    try:
        same = python_ast(old_text) == python_ast(new_text)
    except SyntaxError as exc:
        return f'Python comparison failed: {exc.msg}'
    return None if same else 'Python AST (without comments) would change'


def lex_gitignore(text):
    kinds = bytearray(len(text))
    for a, b, _ in split_lines(text):
        if text.startswith('#', a) and b > a:
            kinds[a:b] = bytes([LCOM]) * (b - a)
    return kinds


def run_with_temp_file(text, suffix, command_builder):
    """Writes text to a NEW temp file in the system temp folder (never the repository), runs the
    command and removes only that temp file."""
    handle, temp_path = tempfile.mkstemp(prefix='freeedr-clean-', suffix=suffix)
    try:
        with os.fdopen(handle, 'w', encoding='utf-8', newline='') as f:
            f.write(text)
        return subprocess.run(command_builder(temp_path), capture_output=True, timeout=EXTERNAL_CHECK_TIMEOUT)
    finally:
        try:
            os.remove(temp_path)
        except OSError:
            pass


def node_check(text):
    node = shutil.which('node')
    if node is None:
        return 'node.js not found; JavaScript needs `node --check` verification'
    try:
        result = run_with_temp_file(text, '.js', lambda p: [node, '--check', p])
    except (OSError, subprocess.SubprocessError) as exc:
        return f'node --check could not run ({type(exc).__name__})'
    if result.returncode != 0:
        lines = result.stderr.decode('utf-8', errors='replace').strip().splitlines()
        detail = next((l for l in lines if 'Error' in l), lines[-1] if lines else 'syntax error')
        return 'node --check failed: ' + detail.strip()
    return None


PS_TOKENIZER = (
    "$ErrorActionPreference='Stop';"
    "$t=[IO.File]::ReadAllText('{path}',[Text.UTF8Encoding]::new($false));"
    "$tk=$null;$er=$null;"
    "[void][System.Management.Automation.Language.Parser]::ParseInput($t,[ref]$tk,[ref]$er);"
    "$o=@(foreach($k in $tk){{$n=[string]$k.Kind;"
    "if($n -eq 'Comment' -or $n -like 'String*' -or $n -like 'HereString*'){{,@($n,$k.Extent.StartOffset,$k.Extent.EndOffset)}}}});"
    "$e=@(foreach($x in $er){{[string]$x.Extent.StartLineNumber+': '+$x.Message}});"
    "ConvertTo-Json -Compress -Depth 4 -InputObject @{{errors=$e;tokens=$o}}"
)
PS_HELP_RE = re.compile(r'(?im)^\s*\.(?:SYNOPSIS|DESCRIPTION|PARAMETER|EXAMPLE|NOTES|OUTPUTS|INPUTS|LINK)\b')


def utf16_to_index(text):
    """Map from UTF-16 code-unit offsets (what .NET reports) to Python string indexes."""
    if all(ord(ch) < 0x10000 for ch in text):
        return lambda off: off
    table = []
    for idx, ch in enumerate(text):
        table.append(idx)
        if ord(ch) >= 0x10000:
            table.append(idx)
    table.append(len(text))
    return lambda off: table[min(off, len(table) - 1)]


def analyze_powershell(text):
    shell = shutil.which('powershell') or shutil.which('pwsh')
    if shell is None:
        raise LexError('PowerShell not found; PowerShell files need its parser for lexing')
    try:
        result = run_with_temp_file(text, '.ps1', lambda p: [
            shell, '-NoProfile', '-NonInteractive', '-Command', PS_TOKENIZER.format(path=p.replace("'", "''"))])
        data = json.loads(result.stdout.decode('utf-8', errors='strict') or 'null')
    except (OSError, subprocess.SubprocessError, ValueError, UnicodeError) as exc:
        raise LexError(f'PowerShell tokenizer failed ({type(exc).__name__})')
    if result.returncode != 0 or not isinstance(data, dict):
        raise LexError('PowerShell tokenizer failed: ' + result.stderr.decode('utf-8', errors='replace').strip()[:200])
    to_index = utf16_to_index(text)
    kinds = bytearray(len(text))
    for token in data.get('tokens') or []:
        name, a, b = token[0], to_index(token[1]), to_index(token[2])
        if name == 'Comment':
            body = text[a:b]
            kind = (DOC if PS_HELP_RE.search(body) else BCOM) if body.startswith('<#') else LCOM
        else:
            kind = STR
        kinds[a:b] = bytes([kind]) * (b - a)
    errors = data.get('errors') or []
    return kinds, ('PowerShell parse errors: ' + '; '.join(errors[:3])) if errors else None


def xml_check(text):
    try:
        ET.fromstring(text)
    except ET.ParseError as exc:
        return f'XML parse failed: {exc}'
    return None


def xml_shape(element):
    """Comment-free element tree. Whitespace-only text is formatting and compares as empty; any
    text with content compares EXACTLY."""
    def text(value):
        return '' if value is None or not value.strip() else value
    return (element.tag, sorted(element.attrib.items()), text(element.text), text(element.tail),
            [xml_shape(child) for child in element])


def xml_equivalent(old_text, new_text):
    try:
        same = xml_shape(ET.fromstring(old_text)) == xml_shape(ET.fromstring(new_text))
    except ET.ParseError as exc:
        return f'XML comparison failed: {exc}'
    return None if same else 'XML content (without comments) would change'


EXPLANATORY_KEPT = 'explanatory prose (kept because --safe was given)'
CODE_LIKE_RE = re.compile(
    r'''^(?:
        [{}()\];,]+                                                         # lone braces / punctuation
      | .*[;{}]                                                             # statement / block opener / closer ends it
      | \[\w+(?:\(.*\))?\]                                                  # attribute
    )$''', re.VERBOSE)
STATEMENT_START_RE = re.compile(
    r'''^(?:[{}()\];,]
      | \[\w
      | (?:return|var|let|const|new|await|throw|break|continue|using|if|else|for|foreach|while|switch|case|default|
           yield|async|function|public|private|protected|internal|static|virtual|override|sealed|partial|abstract|
           readonly|unsafe|class|struct|interface|enum|void|string|int|long|bool|double|try|catch|finally|this|base|delete|typeof)\b
      | [A-Za-z_$][\w$]*(?:\??\.[A-Za-z_$][\w$]*)*(?:<[\w,\s<>?\[\]]*>)?\s*
        (?:\(|\[|[-+*/%&|^]?=(?!=)|\+\+|--|\?\?=)
      | [A-Za-z_$][\w$]*(?:<[\w,\s<>?\[\]]*>)?\??\s+[A-Za-z_$][\w$]*\s*(?:=(?!=)|;)
    )''', re.VERBOSE)
PROSE_RUN_RE = re.compile(r"\b[A-Za-z][a-z']+(?:\s+[A-Za-z][a-z']*){3,}")
STRING_IN_COMMENT_RE = re.compile(r'"(?:\\.|[^"\\])*"' + r"|'(?:\\.|[^'\\])*'" + r'|`(?:\\.|[^`\\])*`')
NON_ASCII_LETTER_RE = re.compile(r'[^\W\d_A-Za-z]')
PS_CODE_RE = re.compile(
    r'''^(?:\$[\w:]+(?:\.\w+|\[[^\]]*\])*\s*(?:[-+*/%]?=|\+\+|--).*
      | [A-Z][a-z]+-[A-Z]\w+\b.*
      | (?:if|elseif|else|foreach|for|while|switch|function|param|return|try|catch|finally|throw|exit)\b\s*[({$\-]?.*
      | [{}()\[\];,]+
      | \[[\w.]+\]\s*[$:(].*
    )$''', re.VERBOSE)
XAML_CODE_RE = re.compile(r'^(?:</?[A-Za-z_][\w.:-]*(?:\s[^<>]*)?/?>|<([A-Za-z_][\w.:-]*)(?:\s[^<>]*)?>[^<>]*</\1\s*>)$')


def without_strings(body):
    return STRING_IN_COMMENT_RE.sub('""', body)


def reads_as_prose(body):
    bare = without_strings(body)
    return PROSE_RUN_RE.search(bare) is not None or NON_ASCII_LETTER_RE.search(bare) is not None


def looks_like_c_code(body):
    if not body or CODE_LIKE_RE.match(body) is None or STATEMENT_START_RE.match(body) is None:
        return False
    return not reads_as_prose(body)


def looks_like_ps_code(body):
    return bool(body) and PS_CODE_RE.match(body) is not None and not reads_as_prose(body)


def looks_like_xaml_code(body):
    return bool(body) and XAML_CODE_RE.match(body) is not None and NON_ASCII_LETTER_RE.search(without_strings(body)) is None


PY_CODE_HINT_RE = re.compile(r'[=(\[]|^(?:import|from|return|if|elif|else|for|while|def|class|try|except|finally|with|pass|raise|print)\b')


def looks_like_py_code(body):
    if not body or reads_as_prose(body) or PY_CODE_HINT_RE.search(body) is None:
        return False
    try:
        with warnings.catch_warnings():
            warnings.simplefilter('ignore')
            compile(body if not body.endswith(':') else body + ' pass', '<comment>', 'exec')
        return True
    except (SyntaxError, ValueError):
        return False


CMD_CODE_RE = re.compile(r'(?i)^(?:@?echo|set|if|for|call|goto|exit|pushd|popd|cd|setlocal|endlocal|copy|del|move|start)\b')


def looks_like_cmd_code(body):
    return bool(body) and CMD_CODE_RE.match(body) is not None and not reads_as_prose(body)


@dataclass(frozen=True)
class Language:
    name: str
    extensions: tuple
    analyze: object
    line_prefixes: tuple
    block_open: tuple
    block_close: tuple
    quote_chars: str
    looks_like_code: object
    equivalent: object = None
    brace_check: bool = False
    tab_check: bool = False
    duplicates: bool = False
    prefix_ci: bool = False
    functional: tuple = ()
    empty_block: tuple = ('{', '}')
    empty_block_functional: bool = False
    inline_blocks: bool = False


PY_FUNCTIONAL = (
    ('Python shebang / encoding / tool directive', re.compile(
        r'(?im)^\s*#!|^[ \t\f]*#.*?\bcoding[:=]|#\s*(?:type:|noqa\b|pragma\b|fmt:|pylint:|mypy:|pyright:|isort:)')),
)
CMD_FUNCTIONAL = (
    ('batch line continuation (^ joins the next line)', re.compile(r'(?m)(?<!\^)(?:\^\^)*\^[ \t]*$')),
)

LANGUAGES = {
    'cs': Language('C#', ('.cs',), lambda t: (CSharpLexer(t).run(), None), ('//',), ('/*',), ('*/',), '"\'',
                   looks_like_c_code, brace_check=True, tab_check=True, duplicates=True, inline_blocks=True),
    'ps1': Language('PowerShell', ('.ps1', '.psm1'), analyze_powershell, ('#',), ('<#',), ('#>',), '',
                    looks_like_ps_code, brace_check=True),
    'xaml': Language('XAML / Avalonia AXAML', ('.xaml', '.axaml'), lambda t: (lex_xaml(t), xml_check(t)), (),
                     ('<!--',), ('-->',), '', looks_like_xaml_code, equivalent=xml_equivalent),
    'xml': Language('XML project/manifest/config', ('.csproj', '.props', '.targets', '.xml', '.manifest', '.config'),
                    lambda t: (lex_xaml(t), xml_check(t)), (), ('<!--',), ('-->',), '',
                    looks_like_xaml_code, equivalent=xml_equivalent),
    'js': Language('JavaScript', ('.js',), lambda t: (JsLexer(t).run(), node_check(t)), ('//',), ('/*',), ('*/',),
                   '"\'`', looks_like_c_code, brace_check=True, inline_blocks=True),
    'cmd': Language('Windows batch', ('.cmd', '.bat'), lambda t: (lex_cmd(t), None), ('@rem', 'rem', '::'), (), (), '',
                    looks_like_cmd_code, prefix_ci=True, functional=CMD_FUNCTIONAL,
                    empty_block=('(', ')'), empty_block_functional=True),
    'iss': Language('Inno Setup', ('.iss',), lambda t: (lex_iss(t), None), (';', '//'), ('{', '(*'), ('}', '*)'), '',
                    looks_like_c_code),
    'yar': Language('YARA', ('.yar', '.yara'), lambda t: (YaraLexer(t).run(), None), ('//',), ('/*',), ('*/',), '"',
                    looks_like_c_code, brace_check=True, inline_blocks=True),
    'py': Language('Python', ('.py',), analyze_python, ('#',), (), (), '', looks_like_py_code,
                   equivalent=python_equivalent, functional=PY_FUNCTIONAL),
    'gitignore': Language('.gitignore', ('.gitignore',), lambda t: (lex_gitignore(t), None), ('#',), (), (), '',
                          lambda body: False),
}


def language_for(path):
    name = path.name.lower()
    return next((lang for lang in LANGUAGES.values() if name.endswith(lang.extensions)), None)


def starts_with_any(text, i, prefixes, ci=False):
    for prefix in prefixes:
        segment = text[i:i + len(prefix)]
        if (segment.lower() if ci else segment) == prefix:
            return True
    return False


def lex(text):
    return CSharpLexer(text).run()


def split_lines(text):
    """Returns (start, content_end, line_end) per line; content excludes \\r\\n / \\n."""
    lines, pos, n = [], 0, len(text)
    while pos < n:
        nl = text.find('\n', pos)
        end = n if nl < 0 else nl + 1
        content_end = nl if nl >= 0 else n
        if content_end > pos and text[content_end - 1] == '\r':
            content_end -= 1
        lines.append((pos, content_end, end))
        pos = end
    return lines


@dataclass(frozen=True)
class Options:
    keep_docs: bool = False
    keep_notes: bool = False
    junk_only: bool = False

    @property
    def removable(self):
        return COMMENT_KINDS if self.keep_docs else COMMENT_KINDS | {DOC}


LEFT_IN_PLACE = 'shares a line with code (left in place)'


def protection_reason(comment_text, lang, opts):
    for reason, pattern in FUNCTIONAL_RULES + list(lang.functional):
        if pattern.search(comment_text):
            return reason
    if opts.keep_notes:
        for reason, pattern in NOTE_RULES:
            if pattern.search(comment_text):
                return reason
    return None


def comment_body(line, lang):
    s = line.strip()
    low = s.lower() if lang.prefix_ci else s
    for prefix in lang.line_prefixes:
        if low.startswith(prefix):
            return s[len(prefix):].strip()
    for opener in lang.block_open:
        if s.startswith(opener):
            s = s[len(opener):]
            break
    for closer in lang.block_close:
        if s.endswith(closer):
            s = s[:-len(closer)]
            break
    return s.strip().lstrip('*').strip()


def run_start(kinds, k, floor=0):
    """First index of the run of equal kinds that contains k (not before floor)."""
    kind = kinds[k]
    while k > floor and kinds[k - 1] == kind:
        k -= 1
    return k


def is_line_comment_at(text, i, lang):
    return starts_with_any(text, i, lang.line_prefixes, lang.prefix_ci)


def junk_kind(block_lines, lang):
    """'COMMENTED-OUT CODE' / 'EMPTY COMMENT' when the whole block is knowledge-free, else None."""
    bodies = [comment_body(l, lang) for l in block_lines]
    if all(not b for b in bodies):
        return 'EMPTY COMMENT'
    if all((not b) or lang.looks_like_code(b) for b in bodies):
        return 'COMMENTED-OUT CODE'
    return None


def load_sentinels(root):
    tags = defaultdict(set)
    manifest = root / 'build' / 'sentinels.txt'
    if manifest.exists():
        for raw in manifest.read_text(encoding='utf-8-sig').splitlines():
            line = raw.strip()
            if not line or line.startswith('#') or '=' not in line:
                continue
            tag, path = (part.strip() for part in line.split('=', 1))
            tags[path.lower()].add(tag)
    return tags


SPACE_OPS = set('+-*/%<>=&|!^~?:.')


def is_word_char(ch):
    return bool(ch) and (ch.isalnum() or ch in '_$@#')


def needs_space(before, after):
    """C-like languages: a space between two characters matters only inside a word/number or between
    two operator characters (`a - -b`, `x > >y`)."""
    return (is_word_char(before) and is_word_char(after)) or (before in SPACE_OPS and after in SPACE_OPS)


def tighten(code):
    """Drops spaces that do not matter (see needs_space) from single-spaced code."""
    return ''.join(ch for i, ch in enumerate(code)
                   if ch != ' ' or (0 < i < len(code) - 1 and needs_space(code[i - 1], code[i + 1])))


def token_stream(text, kinds, removable=COMMENT_KINDS, tight=False):
    """Everything except removable comments, with code whitespace normalised. Used to prove that an
    edit changed nothing but comments and blank lines."""
    out, cur_kind, buf = [], None, []
    for i, ch in enumerate(text):
        k = kinds[i]
        if k in removable:
            continue
        if k != cur_kind:
            if buf:
                out.append((cur_kind, ''.join(buf)))
            cur_kind, buf = k, []
        buf.append(ch)
    if buf:
        out.append((cur_kind, ''.join(buf)))
    merged = []
    for k, t in out:
        if merged and merged[-1][0] == k == CODE:
            merged[-1] = (CODE, merged[-1][1] + ' ' + t)
        else:
            merged.append((k, t))
    result = []
    for k, t in merged:
        if k == CODE:
            t = re.sub(r'\s+', ' ', t).strip()
            if tight:
                t = tighten(t)
            if not t:
                continue
        elif k == DOC:
            t = t.strip()
        elif k == PRE:
            t = t.rstrip()
        result.append((k, t))
    return result


def plan_file(path, root, sentinels, opts=Options()):
    """Returns a dict describing the planned edits for one file, or the reason it is skipped."""
    removable = opts.removable
    rel = path.relative_to(root).as_posix()
    lang = language_for(path)
    info = {'path': path, 'rel': rel, 'lang': lang, 'items': [], 'protected': [], 'skip': None,
            'new_bytes': None, 'syntax_problem': None}
    raw = path.read_bytes()
    bom = raw.startswith(b'\xef\xbb\xbf') or path.suffix.lower() in ('.ps1', '.psm1')
    try:
        text = raw[3 if raw.startswith(b'\xef\xbb\xbf') else 0:].decode('utf-8', errors='strict')
    except UnicodeError:
        info['skip'] = 'not valid UTF-8; left untouched'
        return info
    try:
        kinds, syntax_problem = lang.analyze(text)
    except LexError as exc:
        info['skip'] = f'lexer could not fully parse ({exc}); left untouched'
        return info
    info['syntax_problem'] = syntax_problem
    if lang.quote_chars:
        stray = next((i for i, ch in enumerate(text) if ch in lang.quote_chars and kinds[i] == CODE), None)
        if stray is not None:
            info['skip'] = f'lexer sanity check failed (quote outside a literal at line {text.count(chr(10), 0, stray) + 1}); left untouched'
            return info
    info['text'], info['kinds'], info['bom'] = text, kinds, bom
    lines = split_lines(text)
    line_starters = lang.line_prefixes + lang.block_open

    def nonws_kinds(idx):
        a, b, _ = lines[idx]
        return {kinds[j] for j in range(a, b) if not text[j].isspace()}

    def is_blank_code_line(idx):
        a, b, e = lines[idx]
        if text[a:b].strip():
            return False
        probe = a if a < len(text) else len(text) - 1
        return kinds[probe] == CODE if a < e else True

    line_kinds = [nonws_kinds(i) for i in range(len(lines))]
    full_comment = [bool(k) and k <= removable for k in line_kinds]

    def first_nonspace(idx):
        return next(k for k in range(lines[idx][0], lines[idx][1]) if not text[k].isspace())

    def functional_line(idx):
        """A whole-line line comment that must stay: handled alone, so the prose around it can go."""
        if not full_comment[idx] or not is_line_comment_at(text, first_nonspace(idx), lang):
            return False
        line = text[lines[idx][0]:lines[idx][1]]
        return protection_reason(line, lang, Options()) is not None

    is_functional = [functional_line(i) for i in range(len(lines))]
    actions = {}
    i = 0
    while i < len(lines):
        if not full_comment[i]:
            i += 1
            continue
        j = i
        while j + 1 < len(lines) and full_comment[j + 1] and not is_functional[i] and not is_functional[j + 1]:
            j += 1
        a, b = lines[i][0], lines[j][1]
        first_char = first_nonspace(i)
        starts_clean = (starts_with_any(text, first_char, line_starters, lang.prefix_ci)
                        and run_start(kinds, first_char) == first_char)
        last = lines[j]
        tail = text[last[0]:last[1]].rstrip()
        tail_start = run_start(kinds, last[0] + len(tail) - 1)
        ends_clean = is_line_comment_at(text, tail_start, lang) or tail.endswith(lang.block_close)
        block_text = text[a:b]
        reason = protection_reason(block_text, lang, opts)
        prev_code = next((k for k in range(i - 1, -1, -1) if text[lines[k][0]:lines[k][1]].strip()), None)
        next_code = next((k for k in range(j + 1, len(lines)) if text[lines[k][0]:lines[k][1]].strip()), None)
        opener, closer = lang.empty_block
        if (reason is None and (opts.keep_notes or lang.empty_block_functional)
                and prev_code is not None and next_code is not None
                and text[lines[prev_code][0]:lines[prev_code][1]].rstrip().endswith(opener)
                and text[lines[next_code][0]:lines[next_code][1]].lstrip().startswith(closer)):
            reason = 'only content of an otherwise empty block'
        if not (starts_clean and ends_clean):
            reason = reason or 'part of a block comment that shares a line with code'
        block_lines = [text[lines[k][0]:lines[k][1]] for k in range(i, j + 1)]
        kind_label = junk_kind(block_lines, lang)
        if reason is None and opts.junk_only and kind_label is None:
            reason = EXPLANATORY_KEPT
        if reason:
            info['protected'].append({'line': i + 1, 'end': j + 1, 'reason': reason,
                                      'content': text[lines[i][0]:lines[i][1]].strip()})
        else:
            label = kind_label or ('COMMENT' if j == i else 'COMMENT BLOCK')
            for k in range(i, j + 1):
                actions[k] = {'action': 'DELETE', 'type': label,
                              'line': k + 1, 'content': text[lines[k][0]:lines[k][1]].strip()}
        i = j + 1

    for idx, (a, b, e) in enumerate(lines):
        if idx in actions or full_comment[idx] or not line_kinds[idx]:
            continue
        runs, k = [], a
        while k < b:
            if kinds[k] in removable:
                end = k
                while end < b and kinds[end] == kinds[k]:
                    end += 1
                runs.append((k, end))
                k = end
            else:
                k += 1
        if not runs:
            continue
        new_line, removed, labels = text[a:b], [], []
        for start, end in reversed(runs):
            comment = text[start:end]
            if start == a or not text[a:start].strip():
                continue
            if end == b and b < len(text) and kinds[b] == kinds[end - 1] and kinds[b] in removable:
                continue
            trailing = not text[end:b].strip()
            if is_line_comment_at(text, start, lang):
                if not trailing:
                    continue
            elif not (starts_with_any(text, start, lang.block_open) and comment.endswith(lang.block_close)):
                continue
            elif not trailing and not lang.inline_blocks:
                continue
            reason = protection_reason(comment, lang, opts)
            label = junk_kind([comment], lang)
            if reason is None and opts.junk_only and label is None:
                reason = EXPLANATORY_KEPT
            if reason:
                info['protected'].append({'line': idx + 1, 'end': idx + 1, 'reason': reason, 'content': comment})
                continue
            lead = start
            while lead > a and text[lead - 1] in ' \t':
                lead -= 1
            rel_lead, rel_end = lead - a, end - a
            if trailing:
                new_line = new_line[:rel_lead]
            else:
                before, after = new_line[rel_lead - 1], new_line[rel_end]
                keep_space = after not in ' \t' and needs_space(before, after)
                new_line = new_line[:rel_lead] + (' ' if keep_space else '') + new_line[rel_end:]
            removed.append(comment)
            labels.append(label)
        if not removed:
            continue
        label = labels[0] if len(set(labels)) == 1 else None
        actions[idx] = {'action': 'EDIT', 'type': 'INLINE ' + (label or 'COMMENT'), 'line': idx + 1,
                        'content': 'Rem: ' + ' '.join(reversed(removed)), 'new_content': new_line + text[b:e]}

    covered = set(actions)
    for p in info['protected']:
        covered.update(range(p['line'] - 1, p['end']))
    for idx, (a, b, _) in enumerate(lines):
        if idx not in covered and any(kinds[k] in removable and not text[k].isspace() for k in range(a, b)):
            info['protected'].append({'line': idx + 1, 'end': idx + 1, 'reason': LEFT_IN_PLACE,
                                      'content': text[a:b].strip()})

    run, prev_deleted_comment = 0, False
    for idx in range(len(lines)):
        if idx in actions and actions[idx]['action'] == 'DELETE':
            prev_deleted_comment = True
            continue
        if is_blank_code_line(idx):
            run += 1
            limit = 1 if prev_deleted_comment and run > 1 else MAX_BLANK_RUN
            if run > limit:
                actions[idx] = {'action': 'DELETE', 'type': 'EXCESSIVE EMPTY', 'line': idx + 1,
                                'content': '<Excessive Empty>'}
        else:
            run, prev_deleted_comment = 0, False

    if not actions:
        return info
    if syntax_problem:
        info['skip'] = f'original fails its syntax check ({syntax_problem}); left untouched'
        return info
    out = []
    for idx, (a, b, e) in enumerate(lines):
        act = actions.get(idx)
        if act is None:
            out.append(text[a:e])
        elif act['action'] == 'EDIT':
            out.append(act['new_content'])
    new_text = ''.join(out)
    problem = verify_edit(lang, text, kinds, new_text, sentinels.get(rel.lower(), set()), opts)
    if problem:
        info['skip'] = 'self-verification failed (' + problem + '); left untouched'
        return info
    info['items'] = [actions[k] for k in sorted(actions)]
    info['new_text'] = new_text
    info['new_bytes'] = (b'\xef\xbb\xbf' if bom else b'') + new_text.encode('utf-8')
    return info


def verify_edit(lang, old_text, old_kinds, new_text, required_tags, opts=Options()):
    try:
        new_kinds, new_problem = lang.analyze(new_text)
    except LexError as exc:
        return f'edited text no longer lexes: {exc}'
    if new_problem:
        return f'edited text fails its syntax check: {new_problem}'
    tight = lang.inline_blocks
    if (token_stream(old_text, old_kinds, opts.removable, tight)
            != token_stream(new_text, new_kinds, opts.removable, tight)):
        return 'code/string/doc tokens would change'
    if lang.equivalent is not None:
        problem = lang.equivalent(old_text, new_text)
        if problem:
            return problem
    for tag in required_tags:
        if tag not in new_text:
            return f'sentinel tag {tag} would disappear'
    if opts.keep_notes and Counter(TAG_RE.findall(old_text)) != Counter(TAG_RE.findall(new_text)):
        return 'engineering tag count would change'
    old_has_crlf = '\r\n' in old_text
    old_has_lf_only = '\n' in old_text.replace('\r\n', '')
    if old_has_crlf != old_has_lf_only:
        if '\r\n' in new_text and '\n' in new_text.replace('\r\n', ''):
            return 'line endings would become mixed'
    return None


PP_COND_RE = re.compile(r'#\s*(if|elif|else|endif)\b')


def conditional_contexts(text, kinds, lines):
    contexts, stack, next_id = [], [], 0
    for a, b, _ in lines:
        first = a
        while first < b and text[first].isspace():
            first += 1
        if first < b and kinds[first] == PRE:
            m = PP_COND_RE.match(text, first)
            if m:
                kw = m.group(1)
                if kw == 'if':
                    stack.append([next_id, 0])
                    next_id += 1
                elif kw in ('elif', 'else') and stack:
                    stack[-1][1] += 1
                elif kw == 'endif' and stack:
                    stack.pop()
        contexts.append(tuple((f[0], f[1]) for f in stack))
    return contexts


def is_secondary_branch(context):
    return any(branch > 0 for _, branch in context)


def contexts_compatible(c1, c2):
    d1 = dict(c1)
    return all(d1[k] == v for k, v in c2 if k in d1)


def code_only(text, kinds, contexts=None):
    chars = [ch if (kinds[i] == CODE or ch == '\n') else ' ' for i, ch in enumerate(text)]
    if contexts:
        for (a, b, _), ctx in zip(split_lines(text), contexts):
            if is_secondary_branch(ctx):
                chars[a:b] = ' ' * (b - a)
    return ''.join(chars)


def check_syntax(info):
    text, kinds, lang = info.get('text'), info.get('kinds'), info.get('lang')
    if text is None:
        return info['skip']
    issues = []
    if info.get('syntax_problem'):
        issues.append(info['syntax_problem'])
    if lang.brace_check:
        contexts = conditional_contexts(text, kinds, split_lines(text)) if lang.duplicates else None
        code = code_only(text, kinds, contexts)
        if lang.tab_check and '\t' in code:
            issues.append('Contains tabs (outside strings)')
        if code.count('{') != code.count('}'):
            issues.append(f"Mismatched braces in code ({code.count('{')} '{{' vs {code.count('}')} '}}')")
        if code.count('(') != code.count(')'):
            issues.append(f"Mismatched parentheses in code ({code.count('(')} vs {code.count(')')})")
    return '; '.join(issues) or None


MEMBER_MODIFIERS = (r'(?:(?:public|private|protected|internal|static|virtual|override|async|sealed|partial|abstract|'
                    r'readonly|unsafe|new|extern|const|event|volatile|required|file)\s+)*')
DECL_RE = re.compile(
    r'^\s*' + MEMBER_MODIFIERS +
    r'(?P<kw>(?:record\s+)?(?:class|struct)|record|interface|enum|(?:delegate\s+)?'
    r'[\w.]+(?:<[^;=(){}]*>)?(?:\?|\[[,\s]*\])*)'
    r'\s+(?P<name>[A-Za-z_]\w*)\s*(?P<rest>[(<{:;=].*)?$')
TYPE_KW_RE = re.compile(r'^(?:record\s+)?(?:class|struct)$|^(?:record|interface|enum)$')
NOT_A_TYPE = {'return', 'new', 'throw', 'await', 'using', 'else', 'case', 'goto', 'yield', 'namespace', 'var',
              'public', 'private', 'protected', 'internal', 'static', 'virtual', 'override', 'async', 'sealed',
              'partial', 'abstract', 'readonly', 'unsafe', 'extern', 'const', 'event', 'volatile', 'required', 'file'}


def parameter_list(rest):
    start = rest.find('(')
    if start < 0:
        return ''
    depth = 0
    for k in range(start, len(rest)):
        depth += {'(': 1, ')': -1}.get(rest[k], 0)
        if depth == 0:
            return re.sub(r'\s+', ' ', rest[start:k + 1])
    return re.sub(r'\s+', ' ', rest[start:]) + '...'


def analyze_duplicates(info):
    text, kinds, lang = info.get('text'), info.get('kinds'), info.get('lang')
    if text is None or kinds is None or not lang.duplicates:
        return []
    lines = split_lines(text)
    contexts = conditional_contexts(text, kinds, lines)
    found = defaultdict(list)
    current_ns = 'GLOBAL'
    types = []
    depth = 0
    for idx, (a, b, e) in enumerate(lines):
        secondary = is_secondary_branch(contexts[idx])
        while types and types[-1][2] and depth < types[-1][1]:
            types.pop()
        line = text[a:b]
        stripped = line.strip()
        first_non_ws = a
        while first_non_ws < b and text[first_non_ws].isspace():
            first_non_ws += 1
        if stripped and first_non_ws < b and kinds[first_non_ws] == CODE:
            match = DECL_RE.match(line)
            if stripped.startswith('namespace ') and len(stripped.split()) > 1:
                current_ns = stripped.split()[1].rstrip(';{')
            elif match and match['kw'] not in NOT_A_TYPE:
                kw, name = re.sub(r'\s+', ' ', match['kw']), match['name']
                counted = types[-1][1] == depth if types else TYPE_KW_RE.match(kw) is not None
                if counted:
                    scope = '.'.join([current_ns] + [t[0] for t in types])
                    found[(scope, kw, name + parameter_list(match['rest'] or ''))].append((idx + 1, contexts[idx]))
                if TYPE_KW_RE.match(kw) and not secondary:
                    k = a
                    while k < len(text) and not (kinds[k] == CODE and text[k] in '{;'):
                        k += 1
                    if k < len(text) and text[k] == '{':
                        types.append([name, depth + 1, False])
        if not secondary:
            for k in range(a, b):
                if kinds[k] == CODE:
                    if text[k] == '{':
                        depth += 1
                    elif text[k] == '}':
                        depth -= 1
        if types and depth >= types[-1][1]:
            types[-1][2] = True
    duplicates = []
    for (scope, kw, sig), occurrences in found.items():
        clashing = sorted({line for i, (line, ctx) in enumerate(occurrences)
                           for other_line, other_ctx in occurrences[i + 1:]
                           if contexts_compatible(ctx, other_ctx)
                           for line in (line, other_line)})
        if clashing:
            duplicates.append([info['rel'], scope, kw, sig, ", ".join(map(str, clashing))])
    return duplicates


def get_target_files(root_dir, languages):
    extensions = tuple(ext for key in languages for ext in LANGUAGES[key].extensions)
    targets = []
    for current, dirs, files in os.walk(root_dir):
        dirs[:] = sorted((d for d in dirs if d.lower() not in EXCLUDE_FOLDERS), key=str.casefold)
        for file in sorted(files, key=str.casefold):
            name = file.lower()
            if name.endswith(extensions) and not name.endswith(EXCLUDE_FILE_SUFFIXES):
                targets.append(Path(current) / file)
    return targets


def normalized(path):
    return os.path.normcase(os.path.normpath(os.path.abspath(str(path))))


def git_dirty_files(root):
    """Set of normalized absolute paths with uncommitted changes, or None when git is unavailable."""
    def git(*args):
        return subprocess.run(['git', '-C', str(root), *args], capture_output=True, timeout=20, check=True).stdout
    try:
        top = git('rev-parse', '--show-toplevel').decode('utf-8').strip()
        out = git('-c', 'core.quotepath=off', 'status', '--porcelain=v1', '-z', '--untracked-files=all')
    except (OSError, subprocess.SubprocessError, UnicodeError):
        return None
    records = out.decode('utf-8', errors='surrogateescape').split('\0')
    dirty, i = set(), 0
    while i < len(records):
        record = records[i]
        i += 1
        if len(record) < 4:
            continue
        status, rel = record[:2], record[3:]
        dirty.add(normalized(Path(top) / rel))
        if 'R' in status or 'C' in status:
            if i < len(records) and records[i]:
                dirty.add(normalized(Path(top) / records[i]))
            i += 1
    return dirty


def is_read_only(path, st):
    attributes = getattr(st, 'st_file_attributes', 0)
    if attributes & getattr(stat, 'FILE_ATTRIBUTE_READONLY', 0):
        return True
    return not os.access(path, os.W_OK)


def replace_keeping_metadata(path, temp, backup):
    """Puts temp in place of path. Windows: ReplaceFileW keeps the original file's attributes, ACL,
    creation time and streams, and leaves the original bytes in `backup` until this call removes it.
    Elsewhere: permission bits are copied, then os.replace swaps atomically."""
    if os.name != 'nt':
        shutil.copymode(path, temp)
        os.replace(temp, path)
        return
    from ctypes import wintypes
    kernel32 = ctypes.WinDLL('kernel32', use_last_error=True)
    kernel32.ReplaceFileW.argtypes = [wintypes.LPCWSTR, wintypes.LPCWSTR, wintypes.LPCWSTR,
                                      wintypes.DWORD, wintypes.LPVOID, wintypes.LPVOID]
    kernel32.ReplaceFileW.restype = wintypes.BOOL
    if not kernel32.ReplaceFileW(str(path), str(temp), str(backup), 0, None, None):
        err = ctypes.get_last_error()
        if not path.exists() and backup.exists():
            os.replace(backup, path)
        raise OSError(err, 'ReplaceFileW failed: ' + ctypes.FormatError(err).strip())
    backup.unlink()


def write_planned(info):
    """Writes one file; any failure is reported and leaves the original file and the repo as they were."""
    path = info['path']
    temp = path.with_name(path.name + '.freeedr-clean.tmp')
    backup = path.with_name(path.name + '.freeedr-clean.bak')
    created = False
    try:
        st = os.stat(path)
        if path.read_bytes() != ((b'\xef\xbb\xbf' if info['bom'] else b'') + info['text'].encode('utf-8')):
            print(f"{RED}SKIPPED {info['rel']}: file changed since analysis.{RESET}")
            return False
        if st.st_nlink > 1:
            print(f"{RED}SKIPPED {info['rel']}: file has {st.st_nlink} hard links; replacing it would split them.{RESET}")
            return False
        if is_read_only(path, st):
            print(f"{RED}SKIPPED {info['rel']}: file is read-only; clear the attribute yourself if it should change.{RESET}")
            return False
        for leftover in (temp, backup):
            if leftover.exists():
                print(f"{RED}SKIPPED {info['rel']}: leftover file {leftover.name} from an earlier run; "
                      f"check and remove it yourself.{RESET}")
                return False
        with open(temp, 'xb') as handle:
            created = True
            handle.write(info['new_bytes'])
        replace_keeping_metadata(path, temp, backup)
        created = False
    except OSError as exc:
        print(f"{RED}SKIPPED {info['rel']}: could not write ({type(exc).__name__}: {exc}); original kept.{RESET}")
        if created and temp.exists():
            try:
                temp.unlink()
            except OSError:
                print(f"{RED}  Could not remove {temp}; remove it yourself.{RESET}")
        if backup.exists():
            print(f"{RED}  A copy of the original is at {backup}; compare and remove it yourself.{RESET}")
        return False
    if path.read_bytes() != info['new_bytes']:
        print(f"{RED}WRITE VERIFY FAILED: {info['rel']}{RESET}")
        return False
    return True


def print_table(title, data, headers):
    if not data:
        print(f"\n{title}: No issues found.")
        return
    print(f"\n{title}")
    widths = [len(h) for h in headers]
    for row in data:
        for i, val in enumerate(row):
            widths[i] = max(widths[i], len(str(val)))
    widths = [w + 2 for w in widths]
    h_str = " | ".join(f"{h:^{w}}" for h, w in zip(headers, widths))
    print("-" * len(h_str))
    print(h_str)
    print("-" * len(h_str))
    for row in data:
        print(" | ".join(f"{str(val):<{w}}" for val, w in zip(row, widths)))
    print("-" * len(h_str))


def preview(text, limit=60):
    text = text.replace('\t', ' ')
    return (text[:limit] + '..') if len(text) > limit else text


def purge_bytecode_cache(dry_run=False):
    """Removes any __pycache__ / .pyc this tool's folder has accumulated (dry run: only reports them)."""
    tools_dir = Path(__file__).resolve().parent
    found = []
    try:
        for current, dirs, files in os.walk(tools_dir, followlinks=False):
            for name in list(dirs):
                if name == '__pycache__':
                    found.append(Path(current) / name)
                    dirs.remove(name)
            found.extend(Path(current) / f for f in files if f.lower().endswith(('.pyc', '.pyo')))
    except OSError as exc:
        print(f"[!] Could not scan for bytecode cache: {exc}")
        return
    if not found:
        return
    if dry_run:
        print(f"[*] DRY RUN: {len(found)} bytecode cache item(s) found and left in place "
              f"(a normal run removes them): " + ', '.join(str(p.relative_to(tools_dir)) for p in found))
        return
    removed = 0
    for item in found:
        try:
            if item.is_symlink() or not item.is_dir():
                item.unlink()
            else:
                shutil.rmtree(item)
            removed += 1
        except OSError as exc:
            print(f"[!] Could not remove {item}: {exc}")
    print(f"[*] Removed {removed} bytecode cache item(s).")


def main(argv=None):
    parser = argparse.ArgumentParser(description='FreeEDR comment & blank-line cleaner (C#, PowerShell, XAML/AXAML, '
                                                 'XML, JS, batch, Inno Setup, YARA, Python, .gitignore) with '
                                                 'self-verification.')
    parser.add_argument('--dry-run', action='store_true', help='Analyse and report only; never write, delete or prompt.')
    parser.add_argument('--diff', action='store_true', help='Print a unified diff of every planned edit.')
    parser.add_argument('--show-protected', action='store_true', help='List every kept comment with its reason.')
    parser.add_argument('--root', type=Path, default=DEFAULT_ROOT, help='Repository root (default: parent of developer_tools).')
    parser.add_argument('--only', action='append', default=[], help='Limit to repo-relative glob(s), e.g. "src/Edr.Core/*.cs".')
    parser.add_argument('--languages', default=','.join(LANGUAGES),
                        help=f'Comma-separated subset of: {", ".join(LANGUAGES)} (default: all).')
    parser.add_argument('--keep-docs', action='store_true',
                        help='Keep doc comments (///, /** */, PowerShell comment-based help).')
    parser.add_argument('--keep-notes', action='store_true',
                        help='Keep comments with engineering tags, finding/spec anchors, banners, invariant wording '
                             'and Sysmon/Defender references.')
    parser.add_argument('--safe', action='store_true',
                        help='Implies --keep-docs --keep-notes; remove only commented-out code, empty comments and '
                             'extra blank lines. Default: remove every comment except functional ones '
                             '(#Requires, signature blocks, analyzer directives, shebang, batch ^ continuations).')
    args = parser.parse_args(argv)
    opts = Options(keep_docs=args.keep_docs or args.safe, keep_notes=args.keep_notes or args.safe, junk_only=args.safe)
    languages = [l.strip().lower().lstrip('.') for l in args.languages.split(',') if l.strip()]
    unknown = [l for l in languages if l not in LANGUAGES]
    if unknown:
        parser.error(f'unknown language(s): {", ".join(unknown)}')

    for stream in (sys.stdout, sys.stderr):
        try:
            stream.reconfigure(encoding='utf-8', errors='replace')
        except (AttributeError, ValueError):
            pass
    if os.environ.get('NO_COLOR') or not sys.stdout.isatty():
        global RED, GREEN, CYAN, YELLOW, DIM, RESET
        RED = GREEN = CYAN = YELLOW = DIM = RESET = ''
    enable_vt_colors()
    purge_bytecode_cache(args.dry_run)
    root = args.root.resolve()
    if not ((root / 'project_structure.txt').exists() and (root / 'src' / 'Edr.Core').is_dir()):
        print(f"{RED}Not the FreeEDR repository root: {root}{RESET}")
        return 2
    mode = 'SAFE' if args.safe else 'FULL' + ''.join(
        f' +{flag}' for flag, on in (('keep-docs', opts.keep_docs), ('keep-notes', opts.keep_notes)) if on)
    print(f"{CYAN}--- FREEEDR COMMENT CLEANER [{mode} MODE]{' (DRY RUN)' if args.dry_run else ''} ---{RESET}")
    print(f"Target Directory: {root}")
    sentinels = load_sentinels(root)
    files = get_target_files(root, languages)
    if args.only:
        import fnmatch
        files = [f for f in files if any(fnmatch.fnmatchcase(f.relative_to(root).as_posix().lower(), g.lower())
                                         for g in args.only)]
    per_language = Counter(language_for(f).name for f in files)
    print(f"Analyzing {len(files)} files ({', '.join(f'{n} {k}' for k, n in sorted(per_language.items()))}; "
          f"{sum(len(v) for v in sentinels.values())} sentinel tags registered)...")

    plans = [plan_file(f, root, sentinels, opts) for f in files]
    junk_data, protected_counter = [], Counter()
    for info in plans:
        for item in info['items']:
            junk_data.append([info['rel'], item['line'], item['type'], preview(item['content'])])
        for p in info['protected']:
            protected_counter[p['reason']] += 1
    skipped = [[i['rel'], i['skip']] for i in plans if i['skip']]
    to_write = [i for i in plans if i['items'] and not i['skip']]

    print("\n" + "=" * 80)
    print(f"{YELLOW}STEP 1: REVIEW COMMENTS & UNNECESSARY EMPTY LINES{RESET}")
    print("=" * 80)
    print_table("TABLE 1: IDENTIFIED JUNK (COMMENTS & EXCESSIVE EMPTY LINES)", junk_data,
                ["File", "Line", "Type", "Content Preview"])
    if protected_counter:
        print(f"\n{GREEN}KEPT (protected) comments: {sum(protected_counter.values())}{RESET}")
        for reason, count in protected_counter.most_common():
            print(f"  {count:5}  {reason}")
    if args.show_protected:
        rows = [[i['rel'], p['line'] if p['line'] == p['end'] else f"{p['line']}-{p['end']}", p['reason'],
                 preview(p['content'])] for i in plans for p in i['protected']]
        print_table("PROTECTED COMMENTS", rows, ["File", "Line(s)", "Reason", "Content Preview"])
    print_table("FILES LEFT UNTOUCHED", skipped, ["File", "Reason"])
    if args.diff:
        for info in to_write:
            print(f"\n{CYAN}{info['rel']}{RESET}")
            for line in difflib.unified_diff(info['text'].splitlines(), info['new_text'].splitlines(),
                                             'a/' + info['rel'], 'b/' + info['rel'], n=1, lineterm=''):
                color = RED if line.startswith('-') and not line.startswith('---') else \
                    GREEN if line.startswith('+') and not line.startswith('+++') else DIM
                print(f"{color}{line}{RESET}")
    print(f"\nAll {len(to_write)} file(s) with planned edits passed self-verification "
          "(identical code tokens and strings; syntax re-checked for XML/AXAML/PowerShell/JS/Python).")

    exit_code = 0
    if not to_write:
        print("No comments or unnecessary empty lines to remove.")
    elif args.dry_run:
        print(f"\n{CYAN}DRY RUN: no file was written.{RESET}")
    else:
        dirty = git_dirty_files(root) or set()
        uncommitted = sum(1 for i in to_write if normalized(i['path'].resolve()) in dirty)
        if uncommitted:
            print(f"\n{YELLOW}Note: {uncommitted} of these file(s) also have uncommitted changes of your own; "
                  f"`git diff` will show both together.{RESET}")
        print(f"\n{YELLOW}WARNING: this permanently edits {len(to_write)} file(s) "
              f"({sum(len(i['items']) for i in to_write)} line(s)). Review with `git diff`.{RESET}")
        try:
            answer = input(">>> Remove these comments/empty lines from all listed files? (Y/N): ").strip().upper()
        except EOFError:
            print(f"\n{YELLOW}No console input available; treated as N.{RESET}")
            answer = 'N'
        if answer == 'Y':
            written = sum(write_planned(info) for info in to_write)
            print(f"\n{GREEN}Cleanup complete: {written}/{len(to_write)} file(s) written.{RESET}")
            if written != len(to_write):
                exit_code = 2
        else:
            print(f"\n{CYAN}Cleanup cancelled by user.{RESET}")

    print("\n" + "=" * 80)
    print(f"{YELLOW}STEP 2: SYSTEM ANALYSIS (SYNTAX & DUPLICATES, REPORT ONLY){RESET}")
    print("=" * 80)
    syntax_data = [[i['rel'], err] for i in plans if (err := check_syntax(i))]
    print_table("TABLE 2: SYNTAX & INDENTATION WARNINGS", syntax_data, ["File", "Issue"])
    all_dupes = [row for i in plans for row in analyze_duplicates(i)]
    print_table("TABLE 3: SCOPE-AWARE DUPLICATES (C#, REPORT ONLY)", all_dupes,
                ["File", "Scope", "Type", "Signature", "Lines"])
    print(f"\n{CYAN}Done.{RESET}")
    purge_bytecode_cache(args.dry_run)
    return exit_code


if __name__ == "__main__":
    sys.exit(main())
